{
  "id": "council_tax_reduction",
  "benefit": "council_tax_reduction",
  "name": "Council Tax Reduction (pensioners)",
  "version": "2026-27",
  "jurisdiction": ["England", "Wales"],
  "sources": [
    {"url": "https://www.gov.uk/council-tax-reduction", "title": "Council Tax Reduction (GOV.UK)", "retrieved": "2026-10-27"},
    {"url": "https://www.legislation.gov.uk/uksi/2012/2885/contents", "title": "Council Tax Reduction Schemes (Prescribed Requirements) (England) Regulations 2012", "retrieved": "2026-10-27"}
  ],
  "clauses": [
    {"id": "CTR-1", "text": "Council Tax Reduction is available to people on low income or claiming benefits, up to 100% reduction. Each council runs its own scheme; this model covers pensioners in England and Wales.", "source_url": "https://www.gov.uk/council-tax-reduction"},
    {"id": "CTR-2", "text": "The pensioner scheme applies to people who have reached State Pension age.", "source_url": "https://www.legislation.gov.uk/uksi/2012/2885/contents"},
    {"id": "CTR-3", "text": "The applicant must be liable to pay council tax on the home they live in.", "source_url": "https://www.legislation.gov.uk/uksi/2012/2885/contents"},
    {"id": "CTR-4", "text": "People who get the Guarantee Credit of Pension Credit get the maximum reduction (100% of the net council tax charge).", "source_url": "https://www.legislation.gov.uk/uksi/2012/2885/contents"},
    {"id": "CTR-5", "text": "Otherwise, people with capital above £16,000 cannot get a reduction.", "source_url": "https://www.legislation.gov.uk/uksi/2012/2885/contents"},
    {"id": "CTR-6", "text": "Otherwise, the weekly reduction is the weekly net council tax charge (annual net charge divided by 52), less 20% of any weekly income above the applicable amount. The applicable amount is the Pension Credit guarantee amount (£238 single, £363.25 couple). Income from savings follows the Pension Credit rule (£1 a week for every £500, or part of £500, over £10,000). The household is eligible if the weekly reduction is greater than zero.", "source_url": "https://www.legislation.gov.uk/uksi/2012/2885/contents"}
  ],
  "derived": [
    {"name": "weekly_net_council_tax", "expr": {"op": "div", "args": [{"field": "council_tax_annual_net"}, {"const": 52}]}, "clause": "CTR-6"},
    {"name": "applicable_amount", "expr": {"if": {"field": "has_partner", "op": "==", "value": true}, "then": {"const": 363.25}, "else": {"const": 238}}, "clause": "CTR-6"},
    {"name": "income_from_savings", "expr": {"if": {"field": "savings", "op": ">", "value": {"const": 10000}}, "then": {"op": "mul", "args": [{"op": "ceil", "args": [{"op": "div", "args": [{"op": "sub", "args": [{"field": "savings"}, {"const": 10000}]}, {"const": 500}]}]}, {"const": 1}]}, "else": {"const": 0}}, "clause": "CTR-6"},
    {"name": "total_weekly_income", "expr": {"op": "add", "args": [{"field": "weekly_income_total"}, {"derived": "income_from_savings"}]}, "clause": "CTR-6"},
    {"name": "excess_income", "expr": {"op": "max", "args": [{"op": "sub", "args": [{"derived": "total_weekly_income"}, {"derived": "applicable_amount"}]}, {"const": 0}]}, "clause": "CTR-6"},
    {"name": "weekly_reduction", "expr": {"op": "sub", "args": [{"derived": "weekly_net_council_tax"}, {"op": "mul", "args": [{"const": 0.20}, {"derived": "excess_income"}]}]}, "clause": "CTR-6"}
  ],
  "eligibility": {
    "all": [
      {"field": "country", "op": "in", "value": ["England", "Wales"], "clause": "CTR-1"},
      {"field": "age_years", "op": ">=", "value": {"field": "state_pension_age"}, "clause": "CTR-2"},
      {"field": "council_tax_liable", "op": "==", "value": true, "clause": "CTR-3"},
      {
        "any": [
          {"field": "receives_pension_credit", "op": "==", "value": true, "clause": "CTR-4"},
          {
            "all": [
              {"field": "savings", "op": "<=", "value": {"const": 16000}, "clause": "CTR-5"},
              {"derived": "weekly_reduction", "op": ">", "value": {"const": 0}, "clause": "CTR-6"}
            ]
          }
        ]
      }
    ]
  },
  "amount": {
    "expr": {"if": {"field": "receives_pension_credit", "op": "==", "value": true}, "then": {"derived": "weekly_net_council_tax"}, "else": {"derived": "weekly_reduction"}},
    "unit": "weekly",
    "clause": "CTR-6",
    "min_if_unknown": 0
  },
  "questions": {
    "country": "In which country do you live? (England, Wales, Scotland, or Northern Ireland)",
    "age_years": "What is your age in whole years on the assessment date?",
    "state_pension_age": "What is your State Pension age in years?",
    "council_tax_liable": "Are you liable to pay council tax for the home you live in?",
    "receives_pension_credit": "Are you currently receiving Pension Credit (Guarantee Credit)?",
    "savings": "What is the total amount of savings and investments (capital) you and your partner have, in GBP?",
    "weekly_income_total": "What is your total weekly income from all sources (State Pension, private/occupational pensions, other income) for you and your partner, in GBP?",
    "council_tax_annual_net": "What is your annual council tax charge after any single person discount, in GBP?",
    "has_partner": "Do you live with a partner?"
  },
  "already_receiving_field": "receives_pension_credit",
  "notes": "This rule implements the national pensioner Council Tax Reduction scheme for England and Wales as per SI 2012/2885. Each local council may have its own scheme with different parameters; this is a simplified model. The Guarantee Credit of Pension Credit passports to 100% reduction. Capital limit is £16,000. Income taper is 20% of income above the applicable amount (Pension Credit guarantee levels). Savings income is calculated as £1 per week for every £500 or part of £500 over £10,000. The weekly reduction is the weekly net council tax charge minus the taper. Eligibility requires the reduction to be positive. The rule assumes the claimant has reached State Pension age and is liable for council tax."
}
